const startTime = Date.now();
const input = $input.first().json.body || $input.first().json;
const hasToken = !!input.access_token;
const hasUserId = !!input.user_id;
const receivedFields = Object.keys(input);
return [{
  json: {
    success: true,
    data: {
      echo: input.message || "No message provided",
      received_fields: receivedFields,
      has_token: hasToken,
      has_user_id: hasUserId,
      received_at: new Date().toISOString()
    },
    execution_time_ms: Date.now() - startTime
  }
}];
